def sum_floored_to_tens(a: int, b: int) -> int:
    # Integer-divide by 10 then multiply back to drop the unit digit
    return (a // 10) * 10 + (b // 10) * 10

def surround_first_two_last_two(s: str) -> str:
    # First two, the middle untouched, then the last two
    return "[" + s[:2] + "]" + s[2:-2] + "[" + s[-2:] + "]"

def number_with_more_unique_digits(n1: int, n2: int):
    u1 = len(set(str(n1)))
    u2 = len(set(str(n2)))
    if u1 > u2:
        return n1
    elif u2 > u1:
        return n2
    else:
        return (n1, n2)

def count_vowels_and_consonants_in_even_indices(s: str) -> tuple:
    vowels = set("aeiouAEIOU")
    vowel_count = 0
    consonant_count = 0
    for i in range(0, len(s), 2):
        ch = s[i]
        if ch.isalpha():
            if ch in vowels:
                vowel_count += 1
            else:
                consonant_count += 1
    return (vowel_count, consonant_count)

