def process_call_logs(call_logs: list, task: str):
    counts = {}
    durations = {}
    for log in call_logs:
        name = log["name"]
        counts[name] = counts.get(name, 0) + 1
        durations[name] = durations.get(name, 0) + log["duration"]
    if task == "get_call_counts":
        return counts
    if task == "get_total_call_durations":
        return durations
    if task == "most_frequent_caller":
        # Break ties by total duration
        return max(counts, key=lambda name: (counts[name], durations[name]))
